class SafeZone:
    def __enter__(self):
        print("Enter", end=" ")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        print("Exit", end=" ")
        # 檢查異常類型
        if exc_type is ValueError:
            return True
        return False

print("Start", end=" ")
try:
    with SafeZone():
        raise ValueError("Oops")
except ValueError:
    print("Caught", end=" ")
print("Done")

class BaseConfig:
    def __init__(self, env):
        self.env = env

    @staticmethod
    def from_json(json_data):
        return BaseConfig(json_data['env'])

class AppConfig(BaseConfig):
    pass

config = AppConfig.from_json({'env': 'prod'})

from functools import lru_cache

@lru_cache(maxsize=128)
def process_batch(batch_ids):
    # 假設這是一個耗時的運算
    return sum(batch_ids)

# 第一次呼叫
result = process_batch([1, 2, 3])
